CREATE OR REPLACE FUNCTION public.log_work_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; snapshot jsonb; BEGIN snapshot:=to_jsonb(new); IF tg_table_name='works' THEN wid:=new.id; ELSE wid:=(snapshot->>'work_id')::uuid; END IF; INSERT INTO public.work_history(work_id,entity,entity_id,before,after) VALUES(wid,tg_table_name,new.id,CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(old) END,snapshot); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.check_financial_group_total() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE gid uuid; target numeric; actual numeric; BEGIN IF tg_table_name='financial_groups' THEN gid:=new.id; ELSE gid:=(to_jsonb(new)->>'group_id')::uuid; END IF; IF gid IS NULL THEN RETURN new; END IF; SELECT total INTO target FROM public.financial_groups WHERE id=gid; SELECT coalesce(sum(amount),0) INTO actual FROM public.financial_entries WHERE group_id=gid AND NOT canceled; IF actual<>target THEN RAISE EXCEPTION 'Parcelas devem fechar o total do grupo.'; END IF; RETURN new; END $$;